import { $, i, icons, toggleTheme } from './ui.js';

const roles = [
  {id:'employee',name:'Employees',icon:'receipt',title:'Submit it. Then get on with your day.',body:'Add the business details, attach your receipt and follow your claim from review to reimbursement.',items:['Save a draft and finish it later','Submit even before a manager is assigned','Provide bank details after approval'],link:'register.html',cta:'Create an employee account'},
  {id:'manager',name:'Managers',icon:'user-check',title:'Make each decision with the full picture.',body:'Review the claims assigned to you, with the original purchase proof and policy warnings in one place.',items:['See your assigned team’s requests','Approve or reject with a recorded decision','Review policy exceptions without guessing'],link:'login.html',cta:'Sign in to review claims'},
  {id:'finance',name:'Finance',icon:'landmark',title:'Keep approved claims moving.',body:'See which purchases are ready for processing and keep a clear record of every reimbursement.',items:['Receive bank details through private tickets','Record processing and a payment reference','Export authorized records for reporting'],link:'login.html',cta:'Sign in to finance'},
  {id:'admin',name:'Administrators',icon:'settings-2',title:'The right access. Clear company rules.',body:'Manage trusted role assignments, connect employees to managers and maintain your expense policies.',items:['Authorize manager and finance access','Route pending claims when a manager is assigned','Monitor policies, requests and audit history'],link:'login.html',cta:'Sign in to administration'}
];

export function renderLanding(onConfigure) {
  $('#app').innerHTML=`<div class="landing landing-refresh">
    <a class="skip-link" href="#landing-content">Skip to content</a>
    <header class="landing-nav"><a href="index.html" class="brand" aria-label="ExpenseFlow home"><span class="brand-mark">ef</span><span>Expense<span class="brand-light">Flow</span></span></a><nav aria-label="Introduction"><a href="#workflow">How it works</a><a href="#capabilities">Features</a><a href="#team">For your team</a><button class="icon-button theme-toggle" aria-label="Switch theme">${i('moon')}</button><a href="login.html" class="button secondary">Sign in</a><a href="register.html" class="button primary">Get started ${i('arrow-up-right')}</a></nav></header>
    <main class="landing-main" id="landing-content" tabindex="-1">
      <section class="hero"><div class="hero-copy"><span class="hero-tag">LESS PAPERWORK. MORE PEACE OF MIND.</span><h1>Every expense.<br>One clear <span>flow.</span></h1><p>Submit a receipt. Follow every decision. Know what happens next. Business expenses made simpler for your whole team.</p><div class="hero-actions"><a class="button primary" href="register.html">Get started ${i('arrow-right')}</a><a class="button secondary" href="login.html">Sign in to your workspace</a></div><div class="hero-trust"><span>${i('shield-check')} Private receipts</span><span>${i('list-checks')} Clear policies</span><span>${i('route')} Visible progress</span></div></div>
      <div class="hero-workspace" aria-label="Illustrative expense journey"><div class="hero-workspace-top"><span class="mini-brand">Your expense journey</span><span class="preview-label">ILLUSTRATIVE EXAMPLE</span></div><div class="trip-preview"><span class="stat-icon lavender">${i('plane')}</span><div><h2>A meeting in Bengaluru</h2><p>One business trip. Three separate claims.</p></div></div><div class="trip-lines">${[['plane','Travel','₹2,000'],['hotel','Hotel','₹1,500'],['utensils','Food','₹500']].map(([icon,label,amount])=>`<div><span>${i(icon)}${label}</span><strong>${amount}</strong></div>`).join('')}</div><div class="trip-total"><span>Total trip expenses</span><strong>₹4,000</strong></div><ol class="journey-preview"><li>${i('file-check-2')}<span>Submit receipts</span></li><li>${i('user-check')}<span>Manager review</span></li><li>${i('wallet')}<span>Finance records reimbursement</span></li></ol><p class="preview-note">Sample journey only. Demo payments do not transfer money.</p></div></section>
      <section id="workflow" class="landing-section"><div class="section-intro"><div><div class="eyebrow">FROM RECEIPT TO REIMBURSEMENT</div><h2>A simple path. No guesswork.</h2></div><p>Everyone sees their part of the process, with a record of what happened and what comes next.</p></div><div class="landing-steps">${[['01','Submit your expense','Enter what you bought, why it was needed and how you paid. Attach the receipt.'],['02','Check the details','Policy limits and possible duplicates are checked automatically. Warnings go to a reviewer.'],['03','Get a decision','Your assigned manager reviews the purchase and records an approval or a reason for rejection.'],['04','Track reimbursement','After approval, provide bank details through your ticket and follow finance’s progress.']].map(([n,title,body])=>`<article><span>${n}</span><h3>${title}</h3><p>${body}</p></article>`).join('')}</div></section>
      <section id="capabilities" class="landing-section capabilities"><div><div class="eyebrow">THE DETAILS, TAKEN CARE OF</div><h2>Less chasing.<br>More clarity.</h2><p>A shared process keeps receipts, decisions and reimbursement records together, so you can spend less time finding answers.</p><a class="text-button" href="register.html">Start with your first expense ${i('arrow-right')}</a></div><div class="capability-grid">${[['scan-text','From bill to details','Upload a receipt and optionally extract its text. Review and correct every suggestion.'],['shield-check','Review with confidence','See company limits and duplicate warnings alongside the original purchase proof.'],['bell-ring','Know where it stands','Get in-app updates when a claim is reviewed or its reimbursement moves forward.'],['chart-no-axes-combined','See the bigger picture','Explore spending by date, category and department, then export your permitted records.']].map(([icon,title,body])=>`<article>${i(icon)}<h3>${title}</h3><p>${body}</p></article>`).join('')}</div></section>
      <section id="team" class="landing-section"><div class="section-intro"><div><div class="eyebrow">ONE PLATFORM. CLEAR RESPONSIBILITIES.</div><h2>A workspace that fits your role.</h2></div><p>Access comes from your authorized account role. Manager and finance requests require administrator approval.</p></div><div class="role-explorer"><div class="landing-role-tabs" role="tablist" aria-label="Explore workspace roles">${roles.map((r,n)=>`<button type="button" role="tab" id="role-tab-${r.id}" aria-controls="role-panel-${r.id}" aria-selected="${n===0}" tabindex="${n===0?0:-1}" data-role-index="${n}">${i(r.icon)}${r.name}</button>`).join('')}</div>${roles.map((r,n)=>`<div class="landing-role-panel" id="role-panel-${r.id}" role="tabpanel" aria-labelledby="role-tab-${r.id}" tabindex="0" ${n?'hidden':''}><div><h3>${r.title}</h3><p>${r.body}</p><a class="text-button" href="${r.link}">${r.cta} ${i('arrow-right')}</a></div><ul>${r.items.map(item=>`<li>${i('check-circle-2')}${item}</li>`).join('')}</ul></div>`).join('')}</div></section>
      <section class="landing-section landing-questions"><div><div class="eyebrow">A FEW THINGS TO KNOW</div><h2>Start with confidence.</h2></div><div>${[['Can I submit without a reporting manager?','Yes. Your expense and receipt are saved for pending review. An administrator can assign your manager later; you do not need to submit again.'],['Who can approve my expense?','Only an authorized manager assigned to that claim can review it. Selecting a role at sign-up does not grant approval permissions.'],['Does this demonstration transfer money?','No. Finance records a simulated reimbursement and reference. Use sample bank details for the college demonstration.']].map(([q,a])=>`<details><summary>${q}${i('plus')}</summary><p>${a}</p></details>`).join('')}</div></section>
      <section class="landing-cta"><div><span class="eyebrow">YOUR NEXT EXPENSE, ORGANIZED</span><h2>Ready to make it flow?</h2><p>Create your account or return to your team’s workspace.</p></div><div class="hero-actions"><a class="button primary" href="register.html">Get started ${i('arrow-right')}</a><a class="button secondary" href="login.html">Sign in</a></div></section>
    </main><footer class="landing-footer"><div><strong>ExpenseFlow</strong><p>Enterprise Expense Verification & Reimbursement Platform</p><span>College demonstration · No actual bank transfers</span></div><button class="text-button" id="configure-project">${i('settings-2')}Project configuration</button></footer>
  </div>`;
  $('#configure-project').onclick=onConfigure;$('.theme-toggle').onclick=toggleTheme;
  const tabs=[...document.querySelectorAll('.landing-role-tabs [role="tab"]')];
  const select=(index,focus=false)=>{tabs.forEach((tab,n)=>{tab.setAttribute('aria-selected',String(n===index));tab.tabIndex=n===index?0:-1;document.getElementById(tab.getAttribute('aria-controls')).hidden=n!==index;});if(focus)tabs[index].focus();};
  tabs.forEach((tab,n)=>{tab.onclick=()=>select(n);tab.onkeydown=e=>{let next=n;if(e.key==='ArrowRight')next=(n+1)%tabs.length;else if(e.key==='ArrowLeft')next=(n+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();select(next,true);};});icons();
}
